import { images, IMAGE_WIDTHS } from '../../data/images'
import { cn } from '../../lib/cn'

/**
 * Responsive, locally hosted image. Uses WebP renditions generated by
 * scripts/optimise-images.mjs. Below-the-fold images lazy-load by default.
 */
export default function Img({ name, alt, sizes = '100vw', priority = false, className, imgClassName, position, ...rest }) {
  const meta = images[name]
  if (!meta) {
    if (import.meta.env.DEV) console.warn(`Unknown image: ${name}`)
    return null
  }
  const srcSet = IMAGE_WIDTHS.map((w) => `/assets/images/${name}-${w}.webp ${w}w`).join(', ')
  const img = (
    <img
      src={`/assets/images/${name}-1200.webp`}
      srcSet={srcSet}
      sizes={sizes}
      width={meta.w}
      height={meta.h}
      alt={alt ?? meta.alt}
      loading={priority ? 'eager' : 'lazy'}
      decoding={priority ? 'sync' : 'async'}
      fetchPriority={priority ? 'high' : undefined}
      className={cn('h-full w-full object-cover', imgClassName)}
      style={position ? { objectPosition: position } : undefined}
      {...rest}
    />
  )
  if (!className) return img
  return <div className={cn('overflow-hidden', className)}>{img}</div>
}
